<?php declare(strict_types=1); session_start(); if(empty($_SESSION['user'])||($_SESSION['user']['rol']??'')!=='superadmin'){http_response_code(403);exit('Acceso no autorizado.');}$config=require __DIR__.'/config.php';function h(string $v):string{return htmlspecialchars($v,ENT_QUOTES,'UTF-8');}try{$pdo=new PDO(sprintf('mysql:host=%s;port=%d;dbname=%s;charset=utf8mb4',$config['host'],$config['port'],$config['database']),$config['user'],$config['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$stores=$pdo->query("SELECT id,nombre FROM tiendas WHERE estado='activa' ORDER BY nombre")->fetchAll();$cats=$pdo->query('SELECT c.id,c.nombre,c.orden,t.nombre AS tienda FROM categorias c JOIN tiendas t ON t.id=c.tienda_id ORDER BY t.nombre,c.orden,c.id')->fetchAll();}catch(Throwable $e){http_response_code(500);exit('No se pudieron cargar las categorías.');}?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Categorías</title><style>body{font-family:system-ui;background:#f6f3ee;margin:0}main{max-width:850px;margin:auto;padding:30px 20px}.card{background:#fff;padding:24px;border-radius:16px;margin:16px 0}label{display:block;margin:9px 0 4px}input,select{box-sizing:border-box;width:100%;padding:9px;border:1px solid #ccc;border-radius:7px}button{margin-top:13px;padding:10px 16px;background:#886c42;color:#fff;border:0;border-radius:7px}a{color:#886c42}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:10px 7px;border-bottom:1px solid #eee}</style></head><body><main><p><a href="panel.php">← Panel</a> · <a href="productos-admin.php">Productos</a></p><section class="card"><h1>Categorías por tienda</h1><form method="post" action="categoria-guardar.php"><label>Tienda</label><select name="tienda_id" required><?php foreach($stores as $s):?><option value="<?=$s['id']?>"><?=h($s['nombre'])?></option><?php endforeach;?></select><label>Nombre de categoría</label><input name="nombre" maxlength="100" required placeholder="Ej. Artesanías"><label>Orden</label><input type="number" name="orden" min="0" value="0"><button>Crear categoría</button></form></section><section class="card"><h2>Categorías registradas</h2><table><thead><tr><th>Tienda</th><th>Categoría</th><th>Orden</th></tr></thead><tbody><?php foreach($cats as $c):?><tr><td><?=h($c['tienda'])?></td><td><?=h($c['nombre'])?></td><td><?=h((string)$c['orden'])?></td></tr><?php endforeach;if(!$cats):?><tr><td colspan="3">No hay categorías registradas.</td></tr><?php endif;?></tbody></table></section></main></body></html>
